Rewrite the following GNU C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
using namespace std;

/* macros */
// memory
#define zeroset(A) memset((A), 0, sizeof((A)))
#define negset(A) memset((A), -1, sizeof((A)))
#define all(c) (c).begin(), (c).end()
#define pb push_back
// for loops
#define forlop(i,n) for (int i=0; i<n; i++)
#define forlp(i,start,n) for (int i=start; i<n; i++)
#define forone(i,n) for (int i=1; i<n; i++)
#define iter(c,it) for (typeof((c).begin()) it = (c).begin(); it!=(c).end(); it++)
#define iterf(c,bg,it) for (typeof((c).begin()) it = bg; it!=(c).end(); it++)
#define riter(c,it) for (typeof((c).rbegin()) it = (c).rbegin(); it!=(c).rend(); it++)
// input & output
#define intscan(d) scanf("%d", &d)
#define llscan(d) scanf("%lld", &d)
#define dscan(d) scanf("%lf", &d)
#define fast ios::sync_with_stdio(false)
#define inpt(a) freopen(a,"r",stdin)
#define otpt(a) freopen(a,"w",stdout)
#define eol "\n"
// types
typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> pii;
typedef pair<double, double> pdd;
typedef pair<ll,ll> pll;
typedef vector<int> vi;
typedef vector<ll> vll;
typedef vector<vector<ll> > matrix;
#define ff first
#define ss second
#define mp make_pair
// constants
#define EPS 1e-9
#define MAXN 1000005
#define INF INT_MAX
#define NINF INT_MIN

string s;
bool vis[MAXN];
ll k,p;
const ll MOD = 1000000007;

void dfs(int i)
{
    if (!vis[i]){
        vis[i] = true;
        dfs((k*i)%p);
    }
}

int main()
{
    fast;
    int n;
    cin >> p >> k;
    ll ans = 1;
    for (int i=1; i<p; ++i)
        if (!vis[i]){
            dfs(i);
            ans *= p;
            ans %= MOD;
        }
    if (k == 1)
        ans *= p;
    ans %= MOD;
    cout << ans;
    return 0;
}

</original_code>
